import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import {approveOptions,approvedOptions,optionPlan,optionUsage} from '../../reda-2/plan-options.mjs';
import {planFingerprint} from '../../reda-2/plan-readiness.mjs';
const base=()=>({schema:6,goal:'Walk',context:{equipment:'home'},schedule:{days:[1,3,5]},exercises:[{id:'extension',side:'left',dose:{sets:3,reps:8,rest:60},instructions:['Saved instruction']}],progressionDraft:{old:true}});
const candidate=p=>({id:'less-rounds',title:'Kortare pass',plan:{...p,exercises:[{...p.exercises[0],dose:{...p.exercises[0].dose,sets:2}}]}});
test('approval is bound to the exact prescription and invalidated by clinical edits',()=>{const p=base(),approved=approveOptions(p,[candidate(p)]);assert.equal(approvedOptions(approved).length,1);assert.equal(approved.progressionDraft,undefined);assert.equal(p.planOptions,undefined);assert.notEqual(planFingerprint(approved),planFingerprint(p));for(const key of ['goal','clinicianNote','reviewDate'])assert.throws(()=>approvedOptions({...approved,[key]:'changed'}));assert.throws(()=>approvedOptions({...approved,exercises:[]}))});
test('effective plan leaves base dose untouched and rejects unknown or stale alternatives',()=>{const p=base(),payload=approveOptions(p,[candidate(p)]),record={id:'plan-a',version:3,payload};const alt=optionPlan(record,'less-rounds');assert.equal(alt.payload.exercises[0].dose.sets,2);assert.equal(record.payload.exercises[0].dose.sets,3);assert.equal(alt.id,'plan-a');assert.equal(alt.optionLabel,'Kortare pass');assert.throws(()=>optionPlan(record,'forged'));assert.throws(()=>optionPlan({...record,payload:{...payload,goal:'changed'}},'less-rounds'))});
test('usage distinguishes approved short completion from partial base sessions and excludes old plans',()=>{const p=base(),record={id:'plan-a',payload:approveOptions(p,[candidate(p)])};const rows=[{plan_id:'plan-a',status:'completed',completed_at:'now',payload:{optionId:'less-rounds'}},{plan_id:'plan-a',status:'partial',completed_at:'now',payload:{}},{plan_id:'old',status:'completed',completed_at:'now',payload:{optionId:'less-rounds'}}];assert.deepEqual(optionUsage(record,rows).map(x=>[x.total,x.completed]),[[1,0],[1,1]])});
test('recovery uses chosen rounds, retains choice in outbox and blocks unknown alternatives',()=>{const ctx={console};ctx.window=ctx;ctx.globalThis=ctx;vm.createContext(ctx);for(const f of ['session-state.js','session-recovery.js'])vm.runInContext(fs.readFileSync('reda-2/'+f,'utf8'),ctx);ctx.RedaPlanOptions={optionPlan};const p=base(),record={id:'plan-a',version:3,payload:approveOptions(p,[candidate(p)])},row={client_session_id:'session-a',plan_id:'plan-a',plan_version:3,started_at:new Date().toISOString(),status:'partial',payload:{optionId:'less-rounds',exercises:[{exerciseId:'extension',status:'partial',roundsDone:1,feedback:null}]}};const restored=ctx.RedaRecovery.fromRow(row,record);assert.equal(restored.optionId,'less-rounds');assert.equal(restored.progress[0].totalRounds,2);assert.equal(ctx.RedaRecovery.fromRow({...row,payload:{...row.payload,optionId:'forged'}},record),null);let saved;const storage={setItem(k,v){saved=JSON.parse(v)}};ctx.RedaRecovery.write(storage,'user-a',record,restored,0);assert.equal(saved.session.optionId,'less-rounds');assert.equal(JSON.stringify(saved).includes('Saved instruction'),false)});
